<?php header('Content-Type: application/json'); require_once('../../config/config.php'); require_once('../../libraries/conexion.php'); session_start(); $idempresa=$_SESSION['id_empresa']??null; if(!$idempresa){ echo json_encode(['error'=>'No empresa']); exit;} $op=$_GET['op']??''; switch($op){ case 'listar': $draw=$_POST['draw']??1;$start=$_POST['start']??0;$length=$_POST['length']??10;$search=$_POST['search']['value']??''; $base='FROM tbl_categoria_laboral WHERE idempresa=:idempresa'; if($search) $base.=' AND (nombre LIKE :s OR descripcion LIKE :s)'; $stmt=$connect->prepare('SELECT COUNT(*) '.$base); $stmt->bindValue(':idempresa',$idempresa); if($search) $stmt->bindValue(':s','%'.$search.'%'); $stmt->execute(); $total=$stmt->fetchColumn(); $stmt=$connect->prepare('SELECT * '.$base.' ORDER BY idcategoria DESC LIMIT :start,:length'); $stmt->bindValue(':idempresa',$idempresa); if($search) $stmt->bindValue(':s','%'.$search.'%'); $stmt->bindValue(':start',intval($start),PDO::PARAM_INT); $stmt->bindValue(':length',intval($length),PDO::PARAM_INT); $stmt->execute(); $rows=$stmt->fetchAll(PDO::FETCH_ASSOC); $data=[]; foreach($rows as $r){ $estado=$r['estado']?'ACTIVO':'INACTIVO'; $badge="<span class='badge bg-".($r['estado']?'success':'danger')."'>$estado</span>"; $data[] = [$r['idcategoria'],htmlspecialchars($r['nombre']),htmlspecialchars($r['descripcion']),$badge,"<button class='btn btn-warning btn-sm editar' id='{$r['idcategoria']}'>Editar</button>","<button class='btn btn-danger btn-sm borrar' id='{$r['idcategoria']}'>Borrar</button>"]; } echo json_encode(['draw'=>intval($draw),'recordsTotal'=>$total,'recordsFiltered'=>$total,'data'=>$data]); break; case 'guardar': $id=intval($_POST['idcategoria']??0); $nombre=$_POST['nombre']??''; $desc=$_POST['descripcion']??''; if($id==0){ $stmt=$connect->prepare('INSERT INTO tbl_categoria_laboral (idempresa,nombre,descripcion) VALUES(:e,:n,:d)'); $ok=$stmt->execute([':e'=>$idempresa,':n'=>$nombre,':d'=>$desc]); echo json_encode(['respuesta'=>$ok?'Creado':'Error']); } else { $stmt=$connect->prepare('UPDATE tbl_categoria_laboral SET nombre=:n,descripcion=:d WHERE idcategoria=:id'); $ok=$stmt->execute([':n'=>$nombre,':d'=>$desc,':id'=>$id]); echo json_encode(['respuesta'=>$ok?'Actualizado':'Error']); } break; case 'buscar': $id=intval($_POST['id']??0); $stmt=$connect->prepare('SELECT * FROM tbl_categoria_laboral WHERE idcategoria=:id'); $stmt->execute([':id'=>$id]); echo json_encode($stmt->fetch(PDO::FETCH_ASSOC)?:[]); break; case 'eliminar': $id=intval($_POST['id']??0); $stmt=$connect->prepare('SELECT estado FROM tbl_categoria_laboral WHERE idcategoria=:id'); $stmt->execute([':id'=>$id]); $f=$stmt->fetch(PDO::FETCH_ASSOC); if($f){ $ne=$f['estado']==1?0:1; $stmt=$connect->prepare('UPDATE tbl_categoria_laboral SET estado=:e WHERE idcategoria=:id'); $stmt->execute([':e'=>$ne,':id'=>$id]); echo json_encode(['respuesta'=>'Estado actualizado']); } else echo json_encode(['respuesta'=>'No encontrado']); break; default: echo json_encode(['error'=>'op no valido']); break; } ?>